// Generated by ai-qa from .qa/scenarios/home.json — regenerated when scenarios change.
import { test, expect, type Locator, type Page } from '@company/ai-qa/playwright';

const PRODUCTS = [
  { name: 'Ceramic Mug', description: 'Hand-glazed, 350 ml.', price: '$18.00' },
  { name: 'Canvas Tote', description: 'Heavyweight organic cotton.', price: '$24.00' },
  { name: 'Dot Notebook', description: 'A5, 160 pages, lay-flat.', price: '$12.00' },
] as const;

const mainNav = (page: Page) => page.getByRole('navigation', { name: 'Main' });
const cartLink = (page: Page) => mainNav(page).getByRole('link', { name: /^Checkout/ });
/** The cart badge (span with aria-label "N items in cart"); matched by label so it works while the nav is collapsed. */
const cartBadge = (page: Page) => page.getByLabel(/^\d+ items? in cart$/);
const productsRegion = (page: Page) => page.getByRole('region', { name: 'Products' });
const productCards = (page: Page) => productsRegion(page).getByRole('listitem');
const menuButton = (page: Page) => page.getByRole('button', { name: /^(Open|Close) menu$/ });

function addButton(page: Page, product: string) {
  return page.getByRole('button', { name: `Add ${product} to cart`, exact: true });
}

async function addToCart(page: Page, product: string, times = 1) {
  for (let i = 0; i < times; i++) {
    await addButton(page, product).click();
  }
}

async function box(locator: Locator) {
  const b = await locator.boundingBox();
  expect(b, 'element should have a bounding box').not.toBeNull();
  return b!;
}

function expectClose(actual: number, expected: number, tolerance: number, label: string) {
  expect(Math.abs(actual - expected), `${label}: expected ~${expected}, got ${actual}`).toBeLessThanOrEqual(tolerance);
}

/** Make sure the header nav is usable (opens the mobile menu when the links are collapsed). */
async function ensureNavVisible(page: Page) {
  if (!(await cartLink(page).isVisible())) {
    await page.getByRole('button', { name: /^(Open|Close) menu$/ }).click();
  }
  await expect(cartLink(page)).toBeVisible();
}

/** Marks the current document so a later check can prove no full page load happened. */
async function markDocument(page: Page) {
  await page.evaluate(() => {
    (window as unknown as Record<string, unknown>).__qaNoReload = true;
  });
}

async function expectDocumentNotReloaded(page: Page) {
  const marker = await page.evaluate(() => (window as unknown as Record<string, unknown>).__qaNoReload);
  expect(marker, 'page must not have been reloaded').toBe(true);
}

test('HOME-001: Home page shows hero and all three products with correct names, descriptions and prices', {
  tag: ['@functional', '@catalog', '@desktop', '@high'],
}, async ({ page }) => {
  await test.step('Open /', async () => {
    await page.goto('/');
  });

  await test.step("Read the h1 and the 'Products' h2", async () => {
    await expect(page.getByRole('heading', { level: 1, name: 'Everyday goods, made well', exact: true })).toBeVisible();
    await expect(page.getByText('Small-batch essentials for your desk and kitchen.', { exact: true })).toBeVisible();

    const region = productsRegion(page);
    await expect(region).toHaveAttribute('id', 'products');
    await expect(region.getByRole('heading', { level: 2, name: 'Products', exact: true })).toBeVisible();
  });

  await test.step('Read each product card in the grid', async () => {
    const cards = productCards(page);
    await expect(cards).toHaveCount(3);

    for (const [i, product] of PRODUCTS.entries()) {
      const card = cards.nth(i);
      await expect(card.getByRole('heading', { level: 3 })).toHaveText(product.name);
      await expect(card.getByText(product.description, { exact: true })).toBeVisible();
      await expect(card.getByText(product.price, { exact: true })).toBeVisible();

      await expect(card.getByRole('button')).toHaveCount(1);
      const button = card.getByRole('button', { name: `Add ${product.name} to cart`, exact: true });
      await expect(button).toBeVisible();
      await expect(button).toHaveText('Add to cart');
    }
  });

  await test.step('Check the header cart badge', async () => {
    await expect(cartBadge(page)).toHaveText('0');
    await expect(cartLink(page)).toHaveAccessibleName(/0 items in cart/);
    await expect(cartLink(page)).toHaveAccessibleName('Checkout 0 items in cart');
  });
});

