    const h1 = await box(page.getByRole('heading', { level: 1, name: 'Everyday goods, made well' }));
    expectClose(h1.height, 96, 2, 'h1 height (2 lines)');
    expectClose(h1.x, 24, 1, 'h1 left gutter');
