test('HOME-010: Tablet viewport (834px) shows a usable header and product grid without overflow', {
  tag: ['@responsive', '@navigation', '@tablet', '@medium'],
}, async ({ page, qa }) => {
  const viewportWidth = page.viewportSize()?.width ?? 834;

  await test.step('Open /', async () => {
    await page.goto('/');
    await expect(page.getByRole('heading', { level: 1 })).toBeVisible();
  });

  await test.step('Check the header nav items on one row and no horizontal scroll', async () => {
    await qa.expectNoHorizontalOverflow();

    const items = [
      page.getByRole('link', { name: 'Demo Shop', exact: true }),
      mainNav(page).getByRole('link', { name: 'Home', exact: true }),
      mainNav(page).getByRole('link', { name: 'Shop all products', exact: true }),
      cartLink(page),
      mainNav(page).getByRole('link', { name: 'Sign in to your account', exact: true }),
    ];
    const boxes = [];
    for (const item of items) {
      await expect(item).toBeVisible();
      boxes.push(await box(item));
    }

    const centerY = boxes.map((b) => b.y + b.height / 2);
    for (const [i, y] of centerY.entries()) {
      expectClose(y, centerY[0], 16, `header item ${i + 1} vertical centre (same row)`);
    }
    for (const [i, b] of boxes.entries()) {
      expect(b.x, `header item ${i + 1} left edge`).toBeGreaterThanOrEqual(0);
      expect(b.x + b.width, `header item ${i + 1} right edge`).toBeLessThanOrEqual(viewportWidth);
      if (i > 0) {
        expect(b.x, `header item ${i + 1} must not overlap item ${i}`).toBeGreaterThanOrEqual(boxes[i - 1].x + boxes[i - 1].width - 0.5);
      }
    }

    for (const item of items) {
      const clipped = await item.evaluate((el) => el.scrollWidth > el.clientWidth + 1);
      expect(clipped, 'header item text must not be clipped').toBe(false);
    }
    await expect(page.getByRole('button', { name: /^(Open|Close) menu$/ })).toBeHidden();
  });

  await test.step('Product cards are readable and buttons are at least 44px high', async () => {
    await expect(productCards(page)).toHaveCount(3);
    for (const [i, product] of PRODUCTS.entries()) {
      const card = productCards(page).nth(i);
      await expect(card.getByRole('heading', { level: 3 })).toHaveText(product.name);
      await expect(card.getByText(product.description, { exact: true })).toBeVisible();
      await expect(card.getByText(product.price, { exact: true })).toBeVisible();

      const truncated = await card.evaluate((el) =>
        Array.from(el.querySelectorAll('*')).some((child) => child.scrollWidth > child.clientWidth + 1),
      );
      expect(truncated, `${product.name} card has truncated text`).toBe(false);

      const cardBox = await box(card);
      expect(cardBox.x + cardBox.width, `${product.name} card right edge`).toBeLessThanOrEqual(viewportWidth);

      const button = addButton(page, product.name);
      await expect(button).toBeVisible();
      expect((await box(button)).height, `${product.name} button height`).toBeGreaterThanOrEqual(44);
    }
  });

  await test.step("Tap 'Add Ceramic Mug to cart'", async () => {
    await addButton(page, 'Ceramic Mug').click();
    await expect(cartBadge(page)).toHaveText('1');
  });
});
